<div class="mt-space-xl p-space-md rounded-xl bg-surface-container-lowest border border-surface-container-high flex flex-wrap items-center justify-between gap-space-md shadow-sm">
<div class="flex items-center gap-2 text-secondary font-body-sm text-body-sm">
<span class="material-symbols-outlined text-primary text-[18px]">info</span>
<span class="">All fields marked with an asterisk (<span class="text-primary">*</span>) are mandatory for shelter compliance and Texas Dept of Health animal shelter auditing.</span>
</div>
<div class="flex items-center gap-space-sm ml-auto">
<button class="px-space-md py-2 rounded bg-surface border border-outline-variant/50 hover:bg-surface-container text-secondary hover:text-on-surface font-label-md font-semibold transition-colors" type="button">
        Cancel &amp; Revert
      </button>
<button class="px-space-xl py-2 rounded bg-primary text-on-primary hover:bg-primary-container font-label-md font-semibold transition-all shadow-md flex items-center gap-2" id="btnSubmitInvite" type="button">
<span class="material-symbols-outlined text-[18px]">how_to_reg</span>
<span class="">Send Invitation &amp; Provision Staff Account</span>
</button>
</div>
</div>
</div>
<!-- Client-side Interactive Synchronization Script -->
<script>
  (function() {
    const fName = document.getElementById('inputFirstName');
    const lName = document.getElementById('inputLastName');
    const email = document.getElementById('inputEmail');
    const dept = document.getElementById('selectDept');
    const facility = document.getElementById('selectFacility');
   
    const summaryName = document.getElementById('summaryName');
    const summaryEmail = document.getElementById('summaryEmail');
    const avatar = document.getElementById('avatarPreview');
    const summaryDept = document.getElementById('summaryDept');
    const summaryFacility = document.getElementById('summaryFacility');
    const summaryTierBadge = document.getElementById('summaryTierBadge');

    function updateProfile() {
      const first = (fName.value || '').trim();
      const last = (lName.value || '').trim();
      const full = (first + ' ' + last).trim() || 'New Staff Member';
      summaryName.textContent = full;
      summaryEmail.textContent = email.value || 'pending@adoptly.org';
     
      const initials = ((first ? first[0] : '') + (last ? last[0] : '')).toUpperCase() || 'ST';
      avatar.textContent = initials;
      summaryDept.textContent = dept.value;
      summaryFacility.textContent = facility.value.split('(')[0].trim();
    }

    if(fName) fName.addEventListener('input', updateProfile);
    if(lName) lName.addEventListener('input', updateProfile);
    if(email) email.addEventListener('input', updateProfile);
    if(dept) dept.addEventListener('change', updateProfile);
    if(facility) facility.addEventListener('change', updateProfile);

    // Interactive Tier Card Selector
    const cards = document.querySelectorAll('.tier-card');
    cards.forEach(card => {
      card.addEventListener('click', () => {
        cards.forEach(c => {
          c.classList.remove('border-primary', 'shadow-sm');
          c.classList.add('border-surface-container-high');
          const dot = c.querySelector('.tier-indicator span');
          const circle = c.querySelector('.tier-indicator');
          if (dot) dot.classList.add('hidden');
          if (circle) {
            circle.classList.remove('border-primary');
            circle.classList.add('border-secondary');
          }
        });

        card.classList.remove('border-surface-container-high');
        card.classList.add('border-primary', 'shadow-sm');
        const activeDot = card.querySelector('.tier-indicator span');
        const activeCircle = card.querySelector('.tier-indicator');
        if (activeDot) {
          activeDot.classList.remove('hidden');
          activeDot.classList.add('block', 'bg-primary');
        }
        if (activeCircle) {
          activeCircle.classList.remove('border-secondary');
          activeCircle.classList.add('border-primary', 'border-2');
        }

        const tier = card.getAttribute('data-tier');
        if(summaryTierBadge) {
          if (tier === '1') {
            summaryTierBadge.textContent = 'TIER 01 · SHELTER ADMIN';
            summaryTierBadge.className = 'px-1.5 py-0.2 rounded font-code-num text-[10px] font-bold bg-primary-fixed text-on-primary-fixed';
          } else if (tier === '2') {
            summaryTierBadge.textContent = 'TIER 02 · SCREENER';
            summaryTierBadge.className = 'px-1.5 py-0.2 rounded font-code-num text-[10px] font-bold bg-[#fef3c7] text-[#92400e]';
          } else if (tier === '3') {
            summaryTierBadge.textContent = 'TIER 03 · CARETAKER';
            summaryTierBadge.className = 'px-1.5 py-0.2 rounded font-code-num text-[10px] font-bold bg-[#d1fae5] text-[#065f46]';
          } else if (tier === '4') {
            summaryTierBadge.textContent = 'TIER 04 · INSPECTOR';
            summaryTierBadge.className = 'px-1.5 py-0.2 rounded font-code-num text-[10px] font-bold bg-[#e0f2fe] text-[#075985]';
          }
        }
      });
    });

    // Submit Simulation Toast
    const btnSubmit = document.getElementById('btnSubmitInvite');
    if (btnSubmit) {
      btnSubmit.addEventListener('click', () => {
        btnSubmit.disabled = true;
        btnSubmit.innerHTML = '<span class="material-symbols-outlined text-[18px] animate-spin">progress_activity</span> Provisioning Credentials...';
        setTimeout(() => {
          btnSubmit.innerHTML = '<span class="material-symbols-outlined text-[18px]">check_circle</span> Invitation Dispatched!';
          btnSubmit.classList.remove('bg-primary');
          btnSubmit.classList.add('bg-[#10b981]', 'text-white');
        }, 900);
      });
    }
  })();
</script></main></div>
</body></html>
